                   h = shield_thickness_mm, center = true, $fn = 64);
          cylinder(r = bore_diameter_mm / 2 + shield_bore_clearance_mm, 
                   h = shield_thickness_mm + 2 * connect_overlap_mm, center = true, $fn = 64);
