// Chamfered block (hull of corner posts)
module chamfered_block(L, W, H, c) {
  c2 = max(0, min(c, min(L, W)/4));
  hull() {
    for (sx = [-1, 1], sy = [-1, 1]) {
      translate([sx*(L/2 - c2), sy*(W/2 - c2), 0])
        cube([2*c2, 2*c2, H], center=true);
