            cylinder(r=can_r*1.03, h=mount_face_thk_mm, center=true);

        // Rear endbell lip (subtle)
        translate([0,0,z_bot + mount_face_thk_mm/2])
            cylinder(r=can_r*1.02, h=mount_face_thk_mm, center=true);

