// Side buzzer/connector (connected)
module buzzer_side() {
    union() {
        // Buzzer body (connected to can by overlap)
        translate([buzzer_x, 0, buzzer_z])
            cylinder(r=buzzer_r, h=buzzer_height_mm, center=true, $fn=96);

        // Pin on buzzer (connected to buzzer body)
