housing_thickness_mm = 4.2;       //[2:8:0.1]
corner_radius_mm     = 1.2;       //[0:3:0.1]

// Bezel lip on front
bezel_lip_thickness_mm = 1.2;     //[0.5:3:0.1]
bezel_frame_mm         = 2.2;     //[0.5:6:0.1]

