aperture_y0_mm      = 0;          //[-10:10:0.1]
aperture_width_mm   = 62.0;       //[20:73.6:0.1]
aperture_height_mm  = 18.0;       //[8:28.7:0.1]
aperture_depth_mm   = 0.9;        //[0.2:2.5:0.1]

