ffc_side          = -1;           //[-1:1:2]  // -1 = bottom edge (negative Y), +1 = top edge

// Backside components (simple bumps on PCB)
back_components_present = 1;      //[0:1:1]
chip_count = 3;                   //[0:6:1]

// Connectivity overlap (ensures one connected solid)
overlap_mm = 0.6;                 //[0.2:2:0.1]

