        if (pcb_present && ffc_present) {
            notch_w = ffc_width_mm + 2.0;
            notch_l = 2.0;
            notch_t = pcb_thickness_mm + 2*eps;
            notch_yc = ffc_y_edge + ffc_side * (notch_l/2 - 0.2);
            notch_zc = pcb_zc;
            translate([0, notch_yc, notch_zc])
                rbox([notch_w, notch_l, notch_t], 0.4, center=true);
        }
    }
}

