module relief_pocket() {
  // Pocket carved from the "outer" region, leaving walls and bottom thickness.
  // Keep pocket within the L envelope and avoid breaking through.
  pocket_h = max(0, height - pocket_bottom_thickness);
  if (pocket_h > 0) {
