            // ---- CONNECTIVITY FIX: thin vertical rod/pin must be attached (no gap) ----
            // Place rod so its TOP is inside the body by overlap_mm (guaranteed intersection).
            rod_d   = 1.2;
            rod_len = 18.0;

            // Rod top z = body_rear_z + overlap_mm
