  // Fuse drawer placement: on front face, upper-right quadrant
  fuse_x = cutout_width_mm/2 - fuse_w/2;
  fuse_y = cutout_height_mm/2 - fuse_h/2;
  fuse_z = panel_thickness_mm/2 + flange_thickness_mm - fuse_d/2 + overlap_mm;

