module linear_bearing_body() {
    difference() {
        // Outer casing with chamfers
        chamfered_shell(outer_r, length_mm, chamfer_mm);

        // Through bore (slightly extended for clean cut)
        cylinder(r=bore_r, h=length_mm + 2*overlap_mm, center=true);

