                    difference() {
                        cylinder(r=outer_r + overlap_mm, h=groove_length_mm, center=true);
                        cylinder(r=outer_r - groove_depth_mm, h=groove_length_mm + 2*overlap_mm, center=true);
                    }
            }
        }
    }
