      faceplate_cutouts();
    }

    // Optional earth reference bump (adds material, stays connected)
    if (include_earth_cutout)
      earth_reference_bump();

    // Optional connected panel cutout geometry
    if (include_panel_cutout)
      panel_cutout_connected();
  }
}

