    bar_x = nut_length;

    end_block_x = max(2.5, nut_length * 0.28); // modest end blocks (keeps design intent)
    end_block_y = bar_y;
    end_block_z = nut_thickness;

    // Place end blocks so they intersect the bar by 'overlap' (no gaps)
