    if (c <= 0) {
        cube(size, center=center);
    } else {
        minkowski() {
            cube([max(0.01, size[0]-2*c), max(0.01, size[1]-2*c), max(0.01, size[2]-2*c)], center=center);
            sphere(r=c, $fn=24);
        }
    }
