    z_pos = z_on_pcb(rb_h);

    // Add a subtle "foot" that penetrates into PCB to guarantee fusion
    foot_t = overlap + 0.6;
    foot_z = thickness/2 - foot_t/2; // inside PCB volume

    union() {
        color([0.05, 0.2, 0.85])
            translate([x_pos, 0, z_pos])
                rounded_box([rb_l, rb_w, rb_h], r=1.0, center=true);

