    // Profile is a small triangle spanning from minor to major radius.
    translate([0,0,-h/2])
    linear_extrude(height=h,
                  twist=360*h/pitch,
                  slices=ceil((h/pitch)*twist_steps_per_turn),
                  convexity=10)
