  r1 = outer_radius + shift_r;

  // Trapezoid in (r,y)
  pts = [
    [r0, -tooth_w_root/2],
    [r1, -tooth_w_tip/2],
    [r1,  tooth_w_tip/2],
    [r0,  tooth_w_root/2]
  ];

  rounded_poly(pts, tooth_round_mm);
}

