        translate([0, y, height_mm/2 - mount_hole_counterbore_depth_mm - overlap_mm])
            cylinder(h=mount_hole_counterbore_depth_mm + 2*overlap_mm,
                     r=mount_hole_counterbore_diameter_mm/2,
                     center=false);
    }
}

module rail() {
    difference() {
        rail_body();
        mounting_holes();
    }
}

