               rail_height_mm/2 - c + overlap_mm/2])
        rotate([45, 0, 0])
            cube([cutter_len, cutter_y, cutter_z], center=true);

    // Top-left ( -Y, +Z )
    translate([0,
              -rail_width_mm/2 + c - overlap_mm/2,
               rail_height_mm/2 - c + overlap_mm/2])
        rotate([-45, 0, 0])
            cube([cutter_len, cutter_y, cutter_z], center=true);

    // Bottom-right ( +Y, -Z )
