// 2D rounded rectangle (for robust extrusion)
module rounded_rect_2d(L, W, R) {
  R2 = clamp(R, 0, min(L, W)/2);
  hull() {
    for (sx = [-1, 1], sy = [-1, 1])
      translate([sx*(L/2 - R2), sy*(W/2 - R2)])
        circle(r=R2);
  }
